<template><div class="page-content"><div class="content-title"><div><h1>旅行路线管理</h1><p>路线内容会实时同步到装修器预览与旅行页面</p></div><button class="primary-btn compact" @click="open()">＋ 新增路线</button></div><div class="table-toolbar"><div class="search-box">⌕ <input v-model="keyword" placeholder="搜索路线名称 / 旅行社"></div><div class="filter-chip">全部分类⌄</div><div class="filter-chip">全部状态⌄</div><span>共 {{filtered.length}} 条路线</span></div><section class="data-table"><div class="tr th"><span>路线信息</span><span>分类 / 天数</span><span>积分 / 库存</span><span>合作旅行社</span><span>状态</span><span>操作</span></div><div class="tr" v-for="r in filtered" :key="r.id"><div class="route-cell"><img :src="r.image"><div><b>{{r.name}}</b><small>ID: ROUTE-{{String(r.id).padStart(4,'0')}}</small></div></div><div><span class="soft-tag">{{r.category}}</span><small>{{r.days}}</small></div><div><b>{{r.price}} 积分</b><small :class="{warn:r.stock===0}">库存 {{r.stock}}</small></div><div><b>{{r.agency}}</b><small>已绑定</small></div><div><label class="toggle"><input type="checkbox" v-model="r.status" @change="setStatus(r)"><i></i></label><small>{{r.status?'上架中':'已下架'}}</small></div><div class="row-buttons"><button @click="open(r)">编辑</button><button @click="$emit('toast','团期库存设置已打开')">团期</button></div></div></section>
<div v-if="show" class="dialog-mask" @click.self="show=false"><form class="dialog" @submit.prevent="save"><div class="dialog-head"><div><h2>{{editing.id?'编辑':'新增'}}旅行路线</h2><p>完善路线展示与库存信息</p></div><button type="button" @click="show=false">×</button></div><div class="dialog-body"><div class="field"><label>路线名称</label><input v-model="editing.name" required></div><div class="two-fields"><div class="field"><label>路线分类</label><select v-model="editing.category"><option>户外</option><option>研学</option><option>团建</option><option>人文</option></select></div><div class="field"><label>旅行天数</label><input v-model="editing.days" placeholder="5天4夜"></div></div><div class="two-fields"><div class="field"><label>所需积分</label><input type="number" v-model.number="editing.price"></div><div class="field"><label>当前库存</label><input type="number" v-model.number="editing.stock"></div></div><div class="field"><label>合作旅行社</label><input v-model="editing.agency"></div><div class="field"><label>封面图片 URL</label><input v-model="editing.image"></div><img v-if="editing.image" class="form-cover" :src="editing.image"></div><div class="dialog-actions"><button type="button" @click="show=false">取消</button><button class="primary-btn" type="submit">保存路线</button></div></form></div></div></template>
<script setup>import{computed,ref}from'vue';import{api}from'../services/api';const props=defineProps({config:Object});const emit=defineEmits(['toast']);const keyword=ref(''),show=ref(false),editing=ref({});const filtered=computed(()=>props.config.routes.filter(r=>(r.name+r.agency).includes(keyword.value)));const open=r=>{editing.value=r?JSON.parse(JSON.stringify(r)):{id:0,name:'',category:'户外',days:'3天2夜',price:1999,stock:30,agency:'',description:'',status:true,image:''};show.value=true};const save=async()=>{const payload={...editing.value,price:Number(editing.value.price),stock:Number(editing.value.stock)};try{const saved=payload.id?await api.updateRoute(payload):await api.createRoute(payload);const i=props.config.routes.findIndex(r=>r.id===saved.id);if(i>=0)props.config.routes.splice(i,1,{...saved,price:Number(saved.price)});else props.config.routes.unshift({...saved,price:Number(saved.price)});emit('toast','路线已保存到 MySQL')}catch{if(payload.id){const i=props.config.routes.findIndex(r=>r.id===payload.id);props.config.routes.splice(i,1,payload)}else{payload.id=Date.now();props.config.routes.unshift(payload)}emit('toast','后端未连接，路线暂存于本地')}show.value=false};const setStatus=async r=>{try{await api.setRouteStatus(r.id,r.status);emit('toast',r.status?'路线已上架':'路线已下架')}catch{emit('toast','状态已本地更新，后端未连接')}}</script>
